WITH latest_match AS (SELECT s.*, top1.web_event_page FROM sessions s LEFT JOIN LATERAL (SELECT c.page AS web_event_page FROM web_events c WHERE c.session_id = s.id AND c.event_time <= s.started_at ORDER BY c.event_time DESC, c.id DESC LIMIT 1) top1 ON TRUE) SELECT id, customer_id, started_at, web_event_page FROM latest_match ORDER BY web_event_page NULLS FIRST;
